mapper.select:
SELECT EXISTS (
    SELECT 1 FROM attempt a
    WHERE a.id = #{attemptId} AND a.student_id = #{studentId}
      AND NOT EXISTS (SELECT 1 FROM deleted_student d WHERE d.student_id = a.student_id)
      AND EXISTS (
          SELECT 1 FROM answer ans
          LEFT JOIN judgment j ON j.answer_id = ans.id
          WHERE ans.attempt_id = a.id AND (j.process_status IS NULL OR j.process_status <> 'FAILED')
      )
)
